head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil10609";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil10609.onpageload' });
    }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_submit();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_ViewManualKeyWord_onclick
 * @description 「도움말」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_ViewManualKeyWord_onclick = function(e){
    try {
        fn_ViewManualKeyWord(0200000020)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil10609.btn_ViewManualKeyWord_onclick' }); }
};

/**
 * @method
 * @name grd_resultVo_oncellclick
 * @description grd_resultVo 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultVo_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultVo');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resultVo */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["disclsTitle"] === 'Voluntary Disclosure') { await scwin.disclosurePreview(r["applNo"], r["docNo"]); return; }
        await scwin.disclosurePreview(r["applNo"], r["docNo"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultVo.oncellclick' });
    }
};

/**
 * @method
 * @name btn_submit_onclick
 * @description 「제출」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_submit_onclick = async function(e){
    try {
        await scwin.submit()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil10609.btn_submit_onclick' }); }
};

/**
 * @method
 * @name btn_goList_onclick
 * @description 「취소」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_goList_onclick = function(e){
    try {
        scwin.goList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil10609.btn_goList_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_submit
 * @description submit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_submit = async function () {
    const sbmOptions = {
        id: "tx_fn_submit",
        method: "post",
        action: "/esg/writeESGSubmitInfoForm.do?method=esgEngSubmitDocument",
        ref: "dma_submitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_attachPreview
 * @description attach Preview 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_attachPreview = async function () {
    try { return await $c.data.downFile("/submission/attachFileDown.do?method=searchAttachFile", "", ($c.util.getComponent("dma_attachPreviewReq") ? $c.util.getComponent("dma_attachPreviewReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name goList
 * @description go List 처리
 * @returns {void}
 * @hidden N
 */
scwin.goList = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil10602/jldfil10602.xml');
};

/**
 * @method
 * @name disclosurePreview
 * @description disclosure Preview 처리
 * @param {*} applNo applNo
 * @param {*} disclsDocNo disclsDocNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.disclosurePreview = async function (applNo, disclsDocNo) {
    await $c.win.alert("해당 공시는 미리보기가 제공되지 않습니다. 제출 후 KIND 조회시스템을 통해 확인해주세요.");
};

/**
 * @method
 * @name attachPreview
 * @description attach Preview 처리
 * @param {*} docNo docNo
 * @param {*} attachSeq attachSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.attachPreview = async function (docNo, attachSeq) {
    await $c.win.alert("해당 공시는 미리보기가 제공되지 않습니다. 제출 후 KIND 조회시스템을 통해 확인해주세요.");
};

/**
 * @method
 * @name submit
 * @description submit 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submit = async function () {
    (document.submitFrm || { elements: [] }).action = '/esg/writeESGSubmitInfoForm.do?method=esgEngSubmitDocument';
    await scwin.tx_fn_submit();
};
